import * as THREE from './vendor/three.module.js';
import {mergeGeometries} from './vendor/utils/BufferGeometryUtils.js';
export function createWorld(scene,software){
 const scenery=new THREE.Group();scene.add(scenery);const materials=new Map(),obstacles=[],cameraWalls=[],actors=[];
 const boxGeometries=new Map();
 const geometry={box:new THREE.BoxGeometry(1,1,1),rock:new THREE.IcosahedronGeometry(1,0)};
 function mat(color){if(!materials.has(color))materials.set(color,new THREE.MeshLambertMaterial({color,flatShading:true}));return materials.get(color);}
 function box(w,h,d,color,x=0,y=0,z=0,parent=scenery){const key=w+','+h+','+d;if(!boxGeometries.has(key))boxGeometries.set(key,new THREE.BoxGeometry(w,h,d));const m=new THREE.Mesh(boxGeometries.get(key),mat(color));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;if(parent===scenery&&h<=.2&&y<.2){m.renderOrder=y<0?-30:y>.05?-24:-25;m.material.side=THREE.DoubleSide;}parent.add(m);return m;}
 function cylinder(a,b,h,color,x,y,z,parent=scenery,n=7){const m=new THREE.Mesh(new THREE.CylinderGeometry(a,b,h,n),mat(color));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;if(parent===scenery&&h<.1)m.renderOrder=-25;parent.add(m);return m;}
 function stone(x,y,z,s,color='#7f8973',parent=scenery){const m=new THREE.Mesh(geometry.rock,mat(color));m.position.set(x,y,z);m.scale.set(s,s*.7,s*.85);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 let seed=753;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;};
 // Small ground tiles sort correctly in the vector renderer and batch by region.
 for(let x=-120;x<120;x+=16)for(let z=-120;z<120;z+=16){const village=Math.hypot(x+8,z+8)<33;box(16,.16,16,village?(rand()>.5?'#a59b78':'#a99e7d'):(rand()>.5?'#7a865c':'#818d60'),x+8,-.12,z+8);}
 function house(x,z,rot=0){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;scenery.add(g);box(8,3.8,6,'#bdad87',0,1.9,0,g);box(8.2,.35,6.3,'#8e8d78',0,.17,0,g);for(let side of [-1,1]){const roof=box(9,.22,3.65,'#526b66',0,4.05,side*1.45,g);roof.rotation.x=side*.37;for(let j=-4;j<=4;j+=2)box(.08,.06,3.7,'#7b9080',j,.17,0,roof);box(9.2,.12,.2,'#465d58',0,3.54,side*3.05,g);}box(9.3,.22,.25,'#40554e',0,4.7,0,g);box(1.55,2.55,.1,'#63543e',-.4,1.32,3.03,g);box(1.3,1.05,.1,'#384d41',2.3,2.3,3.04,g);for(let i=0;i<3;i++)box(.08,1.1,.15,'#998666',1.85+i*.45,2.3,3.08,g);for(let i of [-3.8,3.8])box(.18,3.8,.2,'#7a6b50',i,1.9,3.07,g);cylinder(.5,.42,.85,'#a68b60',3,.43,3.8,g);obstacles.push({x,z,r:5.5});const collision=new THREE.Mesh(new THREE.BoxGeometry(8.2,4.8,6.4));collision.position.set(x,2.4,z);collision.rotation.y=rot;collision.updateMatrixWorld(true);cameraWalls.push(collision);}
 house(-12,5,.12);house(12,8,-.15);house(-15,-10,.3);house(13,-12,Math.PI);house(-2,-23,0);
 for(let i=0;i<9;i++){const p=box(2.7,.055,3.7,'#c2b18a',0,.015,19-i*4.8);p.rotation.y=Math.sin(i)*.06;}
 cylinder(1.6,1.7,1.1,'#8c9583',-4,.55,-3,scenery,10);cylinder(1.13,1.13,.05,'#405c57',-4,1.12,-3,scenery,10);for(let x of [-5.8,-2.2])box(.16,3,.16,'#74664c',x,1.5,-3);box(4,.17,.18,'#74664c',-4,3,-3);
 function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);scenery.add(g);cylinder(.15,.36,4,'#786b4d',0,2,0,g);const branch=box(.22,2.5,.22,'#786b4d',.5,3.3,0,g);branch.rotation.z=-.5;for(let j=0;j<3;j++){let crown=stone(j*.85-.7,4.2+j*.7,0,2.15-j*.2,['#65794f','#849557','#9fa666'][j],g);crown.scale.y*=.85;}}
 const treeCount=software?42:68;for(let i=0;i<treeCount;i++){let x=rand()*200-100,z=rand()*200-100;if(Math.abs(x)<26&&z>-30&&z<30)continue;if(x>23&&x<60&&z>0&&z<48)continue;tree(x,z,.65+rand()*.65);}tree(-22,21,.9);tree(23,23,1.1);tree(23,-25,1);tree(-22,-29,1.2);
 for(let i=0;i<18;i++){const a=i/18*Math.PI*2,h=20+rand()*40;const m=new THREE.Mesh(new THREE.ConeGeometry(22+rand()*20,h,5),mat(i%2?'#7f9b8c':'#97afa0'));m.position.set(Math.sin(a)*144,h/2-4,Math.cos(a)*144);scenery.add(m);}
 // Crossed tapering rice clumps replace hundreds of individual box stalks.
 for(let row=0;row<3;row++)for(let col=0;col<2;col++){const x=30+col*15,z=8+row*13;box(14,.13,12,'#8d8764',x,.01,z);box(12.7,.05,10.7,'#83a49a',x,.1,z);for(let a=0;a<5;a++)for(let b=0;b<4;b++){const stalk=cylinder(0,.22,.75,'#bdc284',x-5+a*2.5,.5,z-4+b*2.5,scenery,3);stalk.rotation.z=.12;}}
 for(let i=0;i<28;i++){const x=rand()*150-75,z=rand()*160-70;if(Math.abs(x)<22&&z>-30&&z<30)continue;stone(x,.35,z,.45+rand()*.85);}
 function actor(x,z,color='#697b68',scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);const torso=new THREE.Group();torso.position.y=1.25;g.add(torso);box(.73,.95,.45,color,0,0,0,torso);box(.77,.11,.47,'#514d3b',0,-.22,0,torso);box(.15,.54,.025,'#b3a278',-.2,.12,.24,torso);box(.64,.22,.43,color,0,-.5,0,torso);const head=new THREE.Group();head.position.set(0,1.95,0);g.add(head);box(.43,.43,.39,'#c8ab7e',0,0,0,head);box(.45,.12,.42,'#4b4937',0,.2,0,head);for(let side of [-1,1])box(.055,.06,.015,'#494a36',side*.1,.02,.203,head);const hat=cylinder(.04,.66,.24,'#c6b077',0,.35,0,head,10);cylinder(.65,.65,.035,'#b49b62',0,.235,0,head,10);const legs=[],arms=[];for(let side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.2,.86,0);g.add(leg);box(.25,.7,.27,'#4c5e50',0,-.34,0,leg);box(.29,.13,.42,'#3b4e44',0,-.72,.07,leg);legs.push(leg);const arm=new THREE.Group();arm.position.set(side*.48,1.66,0);g.add(arm);box(.24,.6,.25,color,0,-.28,0,arm);box(.18,.18,.19,'#c8ab7e',0,-.64,0,arm);arms.push(arm);}const blade=new THREE.Group();blade.position.set(0,-.75,.03);arms[1].add(blade);box(.09,.7,.055,'#d7e2cc',0,-.45,0,blade);box(.28,.07,.12,'#b8a367',0,-.07,0,blade);box(.09,.21,.09,'#796448',0,.06,0,blade);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,12),new THREE.MeshBasicMaterial({color:'#344b3f',transparent:true,opacity:.2,depthWrite:false}));shadow.renderOrder=-20;shadow.rotation.x=-Math.PI/2;shadow.position.set(x,.012,z);shadow.scale.setScalar(scale);scene.add(shadow);const result={g,torso,head,hat,legs,arms,blade,shadow};actors.push(result);return result;}
 const player=actor(0,15);player.g.rotation.y=Math.PI;const wen=actor(-6,-.5,'#7b7d78');wen.blade.visible=false;wen.g.rotation.y=.5;
 const bosses=[['The Tribute Collector',-42,44,'#8d6752',1.4,160,20],['The Reed Marsh Guardian',66,43,'#657e53',1.9,230,30],['The Mountain Warden',10,-77,'#617986',2.2,320,50]].map(([name,x,z,color,scale,hp,reward])=>{const a=actor(x,z,color,scale);a.hat.visible=false;a.name=name;a.hp=a.max=hp;a.reward=reward;a.home=new THREE.Vector3(x,0,z);a.state='idle';a.timer=0;a.flash=0;const ring=new THREE.Mesh(new THREE.RingGeometry(3.1,3.25,24),new THREE.MeshBasicMaterial({color:'#d5ae65',transparent:true,opacity:.4,side:THREE.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.025,z);scene.add(ring);a.ring=ring;cylinder(10,10,.03,'#a6a17c',x,-.005,z,scenery,24);return a;});
 const post=new THREE.Group();post.position.set(0,0,6);scene.add(post);cylinder(.2,.3,2.2,'#877050',0,1.1,0,post);box(1.4,.2,.2,'#a68d5d',0,1.6,0,post);cylinder(.35,.4,.8,'#c3ac7c',0,1.5,0,post);post.traverse(o=>{if(o.isMesh)o.renderOrder=5;});const dummy={g:post,name:'Training post',hp:300,max:300,dummy:true,flash:0,timer:0};
 const herbs=[];for(let i=0;i<12;i++){const g=new THREE.Group();g.position.set(rand()*145-70,0,rand()*140-55);scene.add(g);for(let j=0;j<3;j++){const leaf=stone(j*.15,.35+j*.14,0,.2,'#dec278',g);leaf.scale.y*=1.8;}herbs.push(g);}
 // Merge static meshes by material and 32 m region; characters stay articulated.
 scenery.updateMatrixWorld(true);const buckets=new Map();scenery.traverse(o=>{if(!o.isMesh)return;const p=o.getWorldPosition(new THREE.Vector3()),key=o.material.uuid+':'+o.renderOrder+':'+Math.floor(p.x/32)+':'+Math.floor(p.z/32);if(!buckets.has(key))buckets.set(key,{material:o.material,renderOrder:o.renderOrder,geometries:[]});const geo=o.geometry.clone().applyMatrix4(o.matrixWorld);buckets.get(key).geometries.push(geo);});scene.remove(scenery);let triangles=0;for(const {material,renderOrder,geometries} of buckets.values()){const geometry=mergeGeometries(geometries,false);geometry.computeBoundingSphere();const mesh=new THREE.Mesh(geometry,material);mesh.castShadow=mesh.receiveShadow=true;mesh.renderOrder=renderOrder;scene.add(mesh);triangles+=(geometry.index?.count??geometry.attributes.position.count)/3;geometries.forEach(g=>g.dispose());}
 return {player,wen,bosses,dummy,herbs,obstacles,cameraWalls,actors,staticTriangles:triangles};
}
